draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw dog park background
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.rect(50, 50, W - 100, H - 100);
  ctx.stroke();

  // Draw first dog
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(150, H / 2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(150, H / 2 + 30);
  ctx.lineTo(150, H / 2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(150, H / 2 + 45);
  ctx.lineTo(120, H / 2 + 75);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(150, H / 2 + 45);
  ctx.lineTo(180, H / 2 + 75);
  ctx.stroke();

  // Draw second dog
  ctx.beginPath();
  ctx.arc(W - 150, H / 2 + 50 + 20 * Math.sin(t), 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 150, H / 2 + 50 + 20 * Math.sin(t) + 30);
  ctx.lineTo(W - 150, H / 2 + 50 + 20 * Math.sin(t) + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 150, H / 2 + 50 + 20 * Math.sin(t) + 45);
  ctx.lineTo(W - 170, H / 2 + 50 + 20 * Math.sin(t) + 75);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 150, H / 2 + 50 + 20 * Math.sin(t) + 45);
  ctx.lineTo(W - 130, H / 2 + 50 + 20 * Math.sin(t) + 75);
  ctx.stroke();

  ctx.restore();
}
